from taf.internal.aliasing import aliasing_scope
from taf.selenium.core.robotkeywords.keywords import SeleniumOAMKeywords
from taf.selenium.sbts_fsm3.common.debug import catch_interface_exception
from taf.selenium.sbts_fsm3.facade import Sbts


class SbtsCommissioning(SeleniumOAMKeywords):
    """
    Class includes all kws related to Commissioning Wizard configuration page.
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope(lookup_arg='sbts', lookup_type=Sbts)

    def __init__(self):
        super(SbtsCommissioning, self).__init__()

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def go_to_commissioning_tab(self, target_tab_path, timeout=60, sbts=None):
        """
        Go to target which will be configured on commissioning modal

        :param target_tab_path: name of target. If there is only one target tab, such as "NR TDD/Basic Cell Settings",
                                "System Module Configuration", directly pass this string;
                                If there are two same target tabs on modal, such as "Basic Cell Settings",
                                parent target tab should be included to locate target tab, such as
                                "Cells Configuration/NR TDD/Basic Cell Settings"
        :type target_tab_path: str
        :param timeout: timeout
        :type timeout: int
        """
        sbts.configuration.commissioning_wizard.go_to_target_path_under_commissioning_tab(target_tab_path, int(timeout))

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def submit(self, sbts=None):
        sbts.configuration.commissioning_wizard.submit()

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def set_bts_name(self, bts_name, sbts=None):
        """
        Configure bts name under "'General BTS/Site Settings" tab.

        Please Call method "go_to_commissioning_tab" to make sure current context is under "General BTS/Site Settings"
        page before calling this method.

        :param bts_name: bts name
        :type bts_name: str
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
                     If not specified, default alias is used: "None"
        :type sbts: str
        """
        sbts.configuration.commissioning_wizard.view_panel.set_bts_name(bts_name)

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def configure_system_module_configuration(self, system_module, product_code=None, add_external_transport_unit=None,
                                              cabinet_position=None, module_location=None, climate_control_profile=None,
                                              radio_protocol_search_order=None, sbts=None):
        """
        Configure under "System Module Configuration" tab.

        Please Call method "go_to_commissioning_tab" to make sure current context is under "System Module Configuration"
        page before calling this method.

        :param system_module: system module name, e.g "ASOE SMOD-1/SMOD_R-1"
        :type system_module: str
        :param product_code: produce code
        :type product_code: str
        :param add_external_transport_unit: add External transport unit
        :type add_external_transport_unit: str
        :param cabinet_position: cabinet position
        :type cabinet_position: str
        :param module_location: module location
        :type module_location: str
        :param climate_control_profile: climate control profile
        :type climate_control_profile: str
        :param radio_protocol_search_order: radio protocol search order
        :type radio_protocol_search_order: str
        :param sbts: alias (string) – (optional) alias that the new sbts object will be identified by.
                     If not specified, default alias is used: "None"
        :type sbts: str
        """
        sbts.configuration.commissioning_wizard.view_panel.configure_system_module_configuration(
            system_module=system_module,
            product_code=product_code,
            add_external_transport_unit=add_external_transport_unit,
            cabinet_position=cabinet_position,
            module_location=module_location,
            climate_control_profile=climate_control_profile,
            radio_protocol_search_order=radio_protocol_search_order
        )
